class Solution {
 public:
  bool isIdealPermutation(vector<int>& nums) {
    int mx = -1;  // the number that is most likely > nums[i + 2]

    for (int i = 0; i + 2 < nums.size(); ++i) {
      mx = max(mx, nums[i]);
      if (mx > nums[i + 2])
        return false;
    }

    return true;
  }
};

